cd /bench/home/work; python3 - <<'EOF'
import re,os,collections
funcs=set()
decl={}
for root,dirs,files in os.walk('internal'):
    dirs[:] = [d for d in dirs if d!='node_modules']
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p=os.path.join(root,f)
        for i,line in enumerate(open(p,encoding='utf8',errors='ignore'),1):
            m=re.match(r'func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*[\(\[]',line)
            if m:
                n=m.group(1)
                funcs.add(n)
                decl.setdefault(n,[]).append(f"{p}:{i}")
counts=collections.Counter()
allgo=[]
for root,dirs,files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('node_modules','.git','web')]
    for f in files:
        if f.endswith('.go'): allgo.append(os.path.join(root,f))
texts={p:open(p,encoding='utf8',errors='ignore').read() for p in allgo}
for n in funcs:
    pat=re.compile(r'(?<![\w.])'+re.escape(n)+r'\s*\(')
    pat2=re.compile(r'\.'+re.escape(n)+r'\s*\(')
    c=0
    for p,t in texts.items():
        for line in t.split('\n'):
            if line.lstrip().startswith('func '): continue
            c+=len(pat.findall(line))+len(pat2.findall(line))
    counts[n]=c
for n,c in counts.most_common(25):
    print(c,n,decl[n][:2])
EOF

